function smallestDivisor(nums: number[], limit: number): number {
  const fits = (d: number): boolean => {
    let sum = 0;
    for (const x of nums) sum += Math.ceil(x / d);
    return sum <= limit;
  };
  let lo = 1, hi = Math.max(...nums);
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    if (fits(mid)) hi = mid;
    else lo = mid + 1;
  }
  return lo;
}

