    def smallestDivisor(self, nums: List[int], limit: int) -> int:
        def fits(d: int) -> bool:
            return sum((x + d - 1) // d for x in nums) <= limit

        lo, hi = 1, max(nums)
        while lo < hi:
            mid = (lo + hi) // 2
            if fits(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo

